export default async function (ctx) {
  const api = (ctx.params.baseUrl || 'https://ai.mmmick.cn').replace(/\/+$/, '') + '/api/v1/admin';
  const call = async (path, opts = {}) => {
    const r = await ctx.http.request({
      url: api + path,
      method: opts.method || 'GET',
      headers: { 'x-api-key': ctx.params.key, ...(opts.body ? { 'Content-Type': 'application/json' } : {}) },
      body: opts.body,
      timeoutMs: 15000,
    });
    if (!r.ok) throw new Error(path + '：HTTP ' + r.status);
    const j = r.json();
    if (j.code !== 0) throw new Error(path + '：' + j.message);
    return j.data;
  };

  const left = (s) => {
    if (s <= 0) return '已重置';
    const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);
    if (d >= 1) return d + '天' + h + '时';
    if (s >= 3600) return Math.floor(s / 3600) + '时' + m + '分';
    return Math.max(1, m) + '分';
  };

  const items = [];
  let max = 0;
  const addWindow = (group, label, ratio, secs) => {
    ratio = Math.min(1, Math.max(0, ratio));
    if (ratio > max) max = ratio;
    items.push({ group, label, value: ratio, text: Math.round(ratio * 100) + '% · ' + left(secs) });
  };
  const addNote = (group, text) => items.push({ group, label: '—', value: null, text });

  // 1. 账号列表（翻页取全）
  let accounts = [];
  let page = 1;
  let d;
  do {
    d = await call('/accounts?page=' + page + '&page_size=100');
    accounts = accounts.concat(d.items || []);
    page++;
  } while ((d.items || []).length > 0 && accounts.length < d.total);
  if (accounts.length === 0) return { text: '无账号', value: 0 };

  // 2. 批量查询 OAuth 类账号的 5h / 7d 窗口
  const batch = await call('/accounts/usage/batch', {
    method: 'POST',
    body: JSON.stringify({ account_ids: accounts.map((a) => Number(a.id)) }),
  });
  const usage = batch.usage || {};
  const errors = batch.errors || {};
  const windows = { five_hour: '5h', seven_day: '7d' };
  const ocWindows = { rolling: '滚动', weekly: '周', monthly: '月' };

  for (const a of accounts) {
    const id = String(a.id);
    const group = a.status === 'active' ? a.name : a.name + '（' + a.status + '）';
    const u = usage[id];
    if (u) {
      for (const [k, label] of Object.entries(windows)) {
        const w = u[k];
        if (w) addWindow(group, label, w.utilization / 100, w.remaining_seconds);
      }
      continue;
    }
    // 3. 不支持批量查询的平台单独补查
    if (a.platform === 'opencode_go') {
      try {
        const snap = (await call('/accounts/' + id + '/opencode-go-usage')).snapshot;
        for (const [k, label] of Object.entries(ocWindows)) {
          const w = snap && snap.data && snap.data[k];
          if (!w) continue;
          if (w.status !== 'ok') { addNote(group, label + '：' + w.status); continue; }
          const secs = w.resets_at ? (Date.parse(w.resets_at) - Date.now()) / 1000 : 0;
          addWindow(group, label, w.percent / 100, secs);
        }
      } catch (e) {
        addNote(group, '查询失败：' + e.message);
      }
      continue;
    }
    addNote(group, errors[id] || '无用量数据');
  }

  return { text: accounts.length + ' 个账号', value: max, items };
}
